async function api(route,body){const r=await fetch('/api/'+route,{method:body?'POST':'GET',headers:{'x-gofer-token':token,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const result=await r.json();if(!r.ok)throw Error(result.error||'Could not complete the request.');return result;}
function cleanItem(x){const {id,rev,...data}=x;return data;}
async function save(changes){$('#save-state').textContent='Saving…';try{state=await api('save',{version:state.version,changes:changes.map(c=>({id:c.id,data:cleanItem(c),deleted:!!c._deleted}))});render();$('#save-state').textContent='Saved on this laptop';return state;}catch(e){$('#save-state').textContent='Save did not finish';throw e;}}
function safely(fn){return async(...args)=>{try{return await fn(...args);}catch(e){toast(e.message);}};}
function button(label,action,cls=''){return `<button type="button" data-action="${action}" class="${cls}">${label}</button>`;}
function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${extra}></label>`;}
function select(label,name,options,value){return `<label>${label}<select name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;}
function area(label,name,value=''){return `<label>${label}<textarea name="${name}">${esc(value||'')}</textarea></label>`;}
function checks(name,options,selected=[]){return `<div class="checks">${options.map(([value,label])=>`<label class="check"><input type="checkbox" name="${name}" value="${esc(value)}" ${selected.includes(String(value))?'checked':''}>${esc(label)}</label>`).join('')}</div>`;}
function empty(title,text,action=''){return `<div class="empty"><span class="empty-mark" aria-hidden="true">✦</span><h3>${title}</h3><p>${text}</p>${action}</div>`;}
function openDialog(title,html,onSubmit){$('#dialog').classList.remove('draft-preview');if($('#dialog').open){$('#dialog').close();}$('#dialog-title').textContent=title;$('#dialog-context').textContent=pageMood[page]?.[0]||'Your training desk';$('#dialog-content').onpaste=null;$('#dialog-content').innerHTML=html;dialogDirty=false;$('#dialog').showModal();$('#dialog-content').oninput=()=>dialogDirty=true;const form=$('#dialog-content form');if(form&&onSubmit)form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{await onSubmit(new FormData(form));dialogDirty=false;$('#dialog').close();}catch(err){let box=form.querySelector('.form-error');if(!box){box=document.createElement('div');box.className='form-error error';form.prepend(box);}box.textContent=err.message;box.scrollIntoView({block:'nearest'});}finally{if(submit)submit.disabled=false;}};bind($('#dialog-content'));const contents=$('#dialog-content'),first=contents.firstChild;queueMicrotask(()=>{if(contents.firstChild===first)polishDialog(contents,title);});}
