function updateShell(){const p=profile();$('#owner').textContent=p.name||'Welcome, adventurer';const ed=editionState(p),chosen=ed.entries.find(e=>e.id===ed.selected);$('#edition').innerHTML=editionMarkup(chosen);$('#edition').hidden=!ed.show||!chosen;$('#footer-owner').textContent=p.name?`${p.name}’s workspace · Your miles. Your way.`:'Your own pace. Your own adventure.';const pending=state.records.filter(r=>!(state.settings.syncedRevs||[]).includes(r.rev)).length;$('#sync-state').textContent=state.conflicts.length?`${state.conflicts.length} conflicts need review`:state.settings.share?`${pending} changes since last sync`:'Saved locally · Ready for your next adventure';document.querySelectorAll('nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));}
