function monthGrid(first,print=false){const d=new Date(first+'T12:00:00'),offset=(d.getDay()+6)%7,days=new Date(d.getFullYear(),d.getMonth()+1,0).getDate(),count=Math.ceil((offset+days)/7)*7,ws=workouts();let grid='';for(let i=0;i<count;i++){const date=day(first,i-offset),outside=date.slice(0,7)!==first.slice(0,7),events=ws.filter(w=>w.date===date);grid+=`<${print?'div':'button'} class="day ${outside?'outside':''} ${date===today()?'today':''}" ${print?'':`data-action="day:${date}" aria-label="${esc(dateName(date))}, ${events.length} workouts"`}><span class="daynum">${Number(date.slice(-2))}</span>${events.slice(0,print?10:2).map(w=>`<span class="event ${eventClass(w)}">${esc(w.title)}${w.ascentFeet!=null&&w.ascentFeet>0?'<br>↑ '+esc(w.ascentFeet)+' ft':''}</span>`).join('')}${!print&&events.length>2?`<small>+${events.length-2} more</small>`:''}</${print?'div':'button'}>`;}const month=ws.filter(w=>w.date.startsWith(first.slice(0,7)));return `<div class="month"><h3>${esc(monthName(first))}</h3><div class="month-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div class="weekday">${x}</div>`).join('')}${grid}</div><div class="weekly">${mileageTotal(month)} planned mi · ${month.filter(w=>w.status==='Completed').length} completed workouts</div></div>`;}
